import React, {useState, useEffect} from "react";
import {Container} from "react-bootstrap"
import {Route, BrowserRouter as Router, Routes} from "react-router-dom"
import Home from "./Home";
// import About from "./About";
import Map from "./Map";
import Login from "./Login";
import Register from "./Register";
import Order from "./Order";
import Empty from "./Empty";
import History from "./History";

const Body = props => {
    const [email, setEmail] = useState('');
    const [isSuccess, setIsSuccess] = useState(false);

    const handlesetEmail = (ema) => {
        console.log("Dữ liệu nhận được từ login: ", ema);
        // send data to order.jsx for send mail in server
        setEmail(ema);
        setIsSuccess(true);
        // console.log("Dữ liệu gửi đi từ body.jsx", isSuccess);
        // bring data to global component(app.jsx)
        props.setEmail(ema);
        props.setIsSuccess(true);
    }

      // In ra console mỗi khi isSuccess thay đổi
    useEffect(() => {
        console.log('isSuccess:', isSuccess);
    }, [isSuccess]);

    return (
        <Container className="container_body">
            <Router>
                <Routes>
                    <Route path="/" exact element={<Home email={email} isSuccess={isSuccess}/>} />
                    <Route path="/map" exact element={<Map email={email} isSuccess={isSuccess}/>} />
                    <Route path="/history" exact element={<History />} />
                    <Route path="/login" exact element={<Login setEmail={handlesetEmail}/>} />
                    <Route path="/register" exact element={<Register />} />
                    {/* <Route path="/getpassword" exact element={<GetPwd />} /> */}
                    <Route path="/order" exact element={<Order email={email} isSuccess={isSuccess}/>} />
                    <Route path="/empty" exact element={<Empty/>} />
                </Routes>
            </Router>
        </Container>
    )
}

export default Body;
